    Ok(j) => Ok(Eval {
      category: match std.json.get(j, "category") { Some(v) => match std.json.as_str(v) { Some(s) => s, None => "" }, None => "" },
      reason: match std.json.get(j, "reason") { Some(v) => match std.json.as_str(v) { Some(s) => s, None => "" }, None => "" }
    }),
    Err(_) => Err("error")
  }

