type Fields = { done: List[Str], cur: Str, quoted: Bool }

fn step(st: Fields, c: Str) -> Fields =
  if c == "\"" then Fields { done: st.done, cur: st.cur, quoted: !st.quoted }
  else if c == "," && !st.quoted then Fields { done: push(st.done, st.cur), cur: "", quoted: false }
  else Fields { done: st.done, cur: st.cur ++ c, quoted: st.quoted }

fn lstrip(s: Str) -> Str = if starts_with(s, " ") then lstrip(slice(s, 1, len(s))) else s

fn rstrip(s: Str) -> Str = let n = len(s) in if n > 0 && slice(s, n - 1, n) == " " then rstrip(slice(s, 0, n - 1)) else s

fn strip(s: Str) -> Str = rstrip(lstrip(s))

fn fields(line: Str) -> List[Str] =
  let st = fold(chars(line), Fields { done: [], cur: "", quoted: false }, step) in
  map(push(st.done, st.cur), strip)

test quoted = fields("a, \"b, c\" ,d") == ["a", "b, c", "d"]

fn index_of_name(xs: List[Str], name: Str, i: Int) -> Int =
  match get(xs, i) { None => -1, Some(x) => if x == name then i else index_of_name(xs, name, i + 1) }

fn blank(s: Str) -> Bool = trim(s) == ""

type Acc = { sum: Int, skipped: Int, col: Int, header: Bool }

# The first row is the header: it is passed over.
fn add_row(a: Acc, row: Str) -> Acc =
  if a.header then Acc { sum: a.sum, skipped: a.skipped, col: a.col, header: false }
  else match get(fields(row), a.col) {
    Some(v) => match to_int(v) {
      Some(n) => Acc { sum: a.sum + n, skipped: a.skipped, col: a.col, header: false },
      None => Acc { sum: a.sum, skipped: a.skipped + 1, col: a.col, header: false },
    },
    None => Acc { sum: a.sum, skipped: a.skipped + 1, col: a.col, header: false },
  }

fn read_rows(acc: List[Str]) -> List[Str] !io =
  match read_line() { None => acc, Some(l) => read_rows(if blank(l) then acc else push(acc, l)) }

fn no_column(name: Str) -> Int !io = { print("error: no column " ++ name); 1 }

fn main(args: List[Str]) -> Int !io =
  match get(args, 0) {
    Some(name) if len(args) == 1 =>
      let rows = read_rows([]) in
      match get(rows, 0) {
        None => no_column(name),
        Some(header) =>
          let col = index_of_name(fields(header), name, 0) in
          if col < 0 then no_column(name)
          else
            let a = fold(rows, Acc { sum: 0, skipped: 0, col: col, header: true }, add_row) in
            { print("sum " ++ from_int(a.sum)); print("skipped " ++ from_int(a.skipped)); 0 },
      },
    _ => { print("usage: csv_sum <column>"); 2 },
  }

# First index of each query in a sorted list (lower-bound binary search).

fn non_empty(s: Str) -> Bool = s != ""

fn number(s: Str) -> Int = match to_int(trim(s)) { Some(n) => n, None => 0 }

# Smallest index in [lo, hi) whose element is >= v (hi if none).
fn lower_bound(xs: List[Int], v: Int, lo: Int, hi: Int) -> Int =
  if lo >= hi then lo
  else
    let mid = (lo + hi) / 2 in
    match get(xs, mid) {
      Some(x) if x < v => lower_bound(xs, v, mid + 1, hi),
      _ => lower_bound(xs, v, lo, mid),
    }

fn find(xs: List[Int], v: Int) -> Int =
  let i = lower_bound(xs, v, 0, len(xs)) in
  match get(xs, i) { Some(x) if x == v => i, _ => -1 }

test first_of_duplicates = find([1, 3, 3, 5], 3) == 1 && find([1, 3, 3, 5], 4) == -1 && find([], 1) == -1

fn queries(xs: List[Int]) -> Int !io =
  match read_line() {
    None => 0,
    Some(q) => { print(from_int(find(xs, number(q)))); queries(xs) },
  }

fn main(args: List[Str]) -> Int !io =
  match read_line() {
    None => 0,
    Some(first) => queries(map(filter(split(first, " "), non_empty), number)),
  }

# Balanced-bracket check per line; reports the 1-based position of the first error.
# Recursive descent over the characters: one recursion level per open bracket.

fn closer(c: Str) -> Str = match c { "(" => ")", "[" => "]", "{" => "}", _ => "" }

fn is_closer(c: Str) -> Bool = c == ")" || c == "]" || c == "}"

# Scans from index i inside a bracket that `want` closes ("" at the top level). Result: the index
# after that closing bracket, or -(error position).
fn scan(cs: List[Str], i: Int, want: Str) -> Int =
  match get(cs, i) {
    None => if want == "" then i else 0 - (len(cs) + 1),
    Some(c) =>
      if closer(c) != "" then
        let next = scan(cs, i + 1, closer(c)) in
        if next < 0 then next else scan(cs, next, want)
      else if is_closer(c) then (if c == want then i + 1 else 0 - (i + 1))
      else scan(cs, i + 1, want),
  }

fn check(line: Str) -> Str =
  let cs = chars(line) in
  let r = scan(cs, 0, "") in
  if r < 0 then "error " ++ from_int(0 - r) else if r < len(cs) then "error " ++ from_int(r) else "ok"

test examples = check("(a[b]{c})") == "ok" && check("(]") == "error 2" && check("((") == "error 3" && check("") == "ok" && check(")(") == "error 1"

fn each_line() -> Int !io = match read_line() { None => 0, Some(l) => { print(check(l)); each_line() } }

fn main(args: List[Str]) -> Int !io = each_line()

# Bank account state machine: commands from stdin, errors as output, final balances by name.

type Acct = { name: Str, balance: Int }

type Step = { accts: List[Acct], out: Option[Str] }

fn balance_of(xs: List[Acct], name: Str, i: Int) -> Option[Int] =
  match get(xs, i) { None => None, Some(a) => if a.name == name then Some(a.balance) else balance_of(xs, name, i + 1) }

fn add(xs: List[Acct], name: Str, delta: Int, i: Int) -> List[Acct] =
  match get(xs, i) {
    None => [],
    Some(a) => concat([if a.name == name then Acct { name: a.name, balance: a.balance + delta } else a], add(xs, name, delta, i + 1)),
  }

fn is_digit(c: Str) -> Bool = c >= "0" && c <= "9"

fn amount(s: Str) -> Option[Int] =
  if len(s) < 1 || len(s) > 12 || len(filter(chars(s), is_digit)) != len(s) then None
  else match to_int(s) { Some(n) if n > 0 => Some(n), _ => None }

fn say(xs: List[Acct], msg: Str) -> Step = Step { accts: xs, out: Some(msg) }

fn quiet(xs: List[Acct]) -> Step = Step { accts: xs, out: None }

fn exists(xs: List[Acct], name: Str) -> Bool = balance_of(xs, name, 0) != None

fn change(xs: List[Acct], name: Str, amt: Str, sign: Int) -> Step =
  match balance_of(xs, name, 0) {
    None => say(xs, "error: no account " ++ name),
    Some(b) => match amount(amt) {
      None => say(xs, "error: invalid amount"),
      Some(n) => if sign < 0 && b < n then say(xs, "error: insufficient funds") else quiet(add(xs, name, sign * n, 0)),
    },
  }

fn transfer(xs: List[Acct], from: Str, to: Str, amt: Str) -> Step =
  match balance_of(xs, from, 0) {
    None => say(xs, "error: no account " ++ from),
    Some(b) =>
      if !exists(xs, to) then say(xs, "error: no account " ++ to)
      else match amount(amt) {
        None => say(xs, "error: invalid amount"),
        Some(n) => if b < n then say(xs, "error: insufficient funds") else quiet(add(add(xs, from, 0 - n, 0), to, n, 0)),
      },
  }

fn tok(ts: List[Str], i: Int) -> Str = match get(ts, i) { Some(t) => t, None => "" }

fn command(xs: List[Acct], line: Str) -> Step =
  let ts = split(line, " ") in
  let n = len(ts) in
  match tok(ts, 0) {
    "open" if n == 2 => if exists(xs, tok(ts, 1)) then say(xs, "error: account " ++ tok(ts, 1) ++ " exists") else quiet(push(xs, Acct { name: tok(ts, 1), balance: 0 })),
    "deposit" if n == 3 => change(xs, tok(ts, 1), tok(ts, 2), 1),
    "withdraw" if n == 3 => change(xs, tok(ts, 1), tok(ts, 2), -1),
    "transfer" if n == 4 => transfer(xs, tok(ts, 1), tok(ts, 2), tok(ts, 3)),
    "balance" if n == 2 => match balance_of(xs, tok(ts, 1), 0) {
      None => say(xs, "error: no account " ++ tok(ts, 1)),
      Some(b) => say(xs, tok(ts, 1) ++ " " ++ from_int(b)),
    },
    _ => say(xs, "error: invalid command"),
  }

test flow = command(quiet([]).accts, "deposit a 1").out == Some("error: no account a")
test amounts = amount("12") == Some(12) && amount("0") == None && amount("+3") == None && amount("1234567890123") == None

fn name_of(a: Acct) -> Str = a.name

fn report(xs: List[Acct], names: List[Str], i: Int) -> Int !io =
  match get(names, i) {
    None => 0,
    Some(n) => { print(n ++ " " ++ from_int(match balance_of(xs, n, 0) { Some(b) => b, None => 0 })); report(xs, names, i + 1) },
  }

fn run(xs: List[Acct]) -> Int !io =
  match read_line() {
    None => { print("---"); report(xs, sort_str(map(xs, name_of)), 0) },
    Some(line) =>
      let s = command(xs, line) in
      match s.out {
        Some(msg) => { print(msg); run(s.accts) },
        None => run(s.accts),
      },
  }

fn main(args: List[Str]) -> Int !io = run([])

# Tokenizer for arithmetic expressions: NUM, ID, OP, LP, RP or the first invalid character.

fn is_digit(c: Str) -> Bool = c >= "0" && c <= "9"

fn is_letter(c: Str) -> Bool = (c >= "a" && c <= "z") || (c >= "A" && c <= "Z") || c == "_"

fn is_word(c: Str) -> Bool = is_letter(c) || is_digit(c)

fn at(cs: List[Str], i: Int) -> Str = match get(cs, i) { Some(c) => c, None => "" }

# End of the run starting at i whose characters satisfy `ok`.
fn run_end(cs: List[Str], i: Int, ok: fn(Str) -> Bool) -> Int = if i < len(cs) && ok(at(cs, i)) then run_end(cs, i + 1, ok) else i

fn text(cs: List[Str], from: Int, to: Int) -> Str = join(slice_list(cs, from, to), "")

fn slice_list(cs: List[Str], from: Int, to: Int) -> List[Str] = if from >= to then [] else concat([at(cs, from)], slice_list(cs, from + 1, to))

fn tokens(cs: List[Str], i: Int, acc: List[Str]) -> Str =
  match get(cs, i) {
    None => join(acc, " "),
    Some(c) =>
      if c == " " || c == "\t" then tokens(cs, i + 1, acc)
      else if is_digit(c) then let e = run_end(cs, i, is_digit) in tokens(cs, e, push(acc, "NUM(" ++ text(cs, i, e) ++ ")"))
      else if is_letter(c) then let e = run_end(cs, i, is_word) in tokens(cs, e, push(acc, "ID(" ++ text(cs, i, e) ++ ")"))
      else if c == "+" || c == "-" || c == "*" || c == "/" || c == "%" then tokens(cs, i + 1, push(acc, "OP(" ++ c ++ ")"))
      else if c == "(" then tokens(cs, i + 1, push(acc, "LP"))
      else if c == ")" then tokens(cs, i + 1, push(acc, "RP"))
      else "error at " ++ from_int(i + 1) ++ ": '" ++ c ++ "'",
  }

fn tokenize(line: Str) -> Str = tokens(chars(line), 0, [])

test example = tokenize("x1 + 42*(y - 7)") == "ID(x1) OP(+) NUM(42) OP(*) LP ID(y) OP(-) NUM(7) RP" && tokenize("3 $ 4") == "error at 3: '$'"

fn each_line() -> Int !io = match read_line() { None => 0, Some(l) => { print(tokenize(l)); each_line() } }

fn main(args: List[Str]) -> Int !io = each_line()

# Integer expression evaluator: tokenize, parse (recursive descent), then evaluate.

type Tok = Num(Int) | Sym(Str)

type E = Lit(Int) | Neg(E) | Bin(Str, E, E)

type Parsed = { e: E, pos: Int }

fn is_digit(c: Str) -> Bool = c >= "0" && c <= "9"

fn digits_end(cs: List[Str], i: Int) -> Int = match get(cs, i) { Some(c) if is_digit(c) => digits_end(cs, i + 1), _ => i }

fn digits(cs: List[Str], from: Int, to: Int, acc: Int) -> Int =
  if from >= to then acc else digits(cs, from + 1, to, acc * 10 + (match get(cs, from) { Some(c) => char_code(c) - 48, None => 0 }))

fn lex(cs: List[Str], i: Int, acc: List[Tok]) -> Option[List[Tok]] =
  match get(cs, i) {
    None => Some(acc),
    Some(c) =>
      if c == " " || c == "\t" then lex(cs, i + 1, acc)
      else if is_digit(c) then let e = digits_end(cs, i) in lex(cs, e, push(acc, Num(digits(cs, i, e, 0))))
      else if contains("+-*/%()", c) then lex(cs, i + 1, push(acc, Sym(c)))
      else None,
  }

fn sym_at(ts: List[Tok], i: Int) -> Str = match get(ts, i) { Some(Sym(s)) => s, _ => "" }

fn expr(ts: List[Tok], i: Int) -> Option[Parsed] = match term(ts, i) { None => None, Some(p) => expr_rest(ts, p) }

fn expr_rest(ts: List[Tok], left: Parsed) -> Option[Parsed] =
  let op = sym_at(ts, left.pos) in
  if op == "+" || op == "-" then
    match term(ts, left.pos + 1) { None => None, Some(r) => expr_rest(ts, Parsed { e: Bin(op, left.e, r.e), pos: r.pos }) }
  else Some(left)

fn term(ts: List[Tok], i: Int) -> Option[Parsed] = match unary(ts, i) { None => None, Some(p) => term_rest(ts, p) }

fn term_rest(ts: List[Tok], left: Parsed) -> Option[Parsed] =
  let op = sym_at(ts, left.pos) in
  if op == "*" || op == "/" || op == "%" then
    match unary(ts, left.pos + 1) { None => None, Some(r) => term_rest(ts, Parsed { e: Bin(op, left.e, r.e), pos: r.pos }) }
  else Some(left)

fn unary(ts: List[Tok], i: Int) -> Option[Parsed] =
  if sym_at(ts, i) == "-" then match unary(ts, i + 1) { None => None, Some(p) => Some(Parsed { e: Neg(p.e), pos: p.pos }) }
  else atom(ts, i)

fn atom(ts: List[Tok], i: Int) -> Option[Parsed] =
  match get(ts, i) {
    Some(Num(n)) => Some(Parsed { e: Lit(n), pos: i + 1 }),
    Some(Sym("(")) => match expr(ts, i + 1) {
      Some(p) if sym_at(ts, p.pos) == ")" => Some(Parsed { e: p.e, pos: p.pos + 1 }),
      _ => None,
    },
    _ => None,
  }

fn eval(e: E) -> Result[Int, Str] =
  match e {
    Lit(n) => Ok(n),
    Neg(x) => match eval(x) { Ok(v) => Ok(0 - v), Err(m) => Err(m) },
    Bin(op, l, r) => match eval(l) {
      Err(m) => Err(m),
      Ok(a) => match eval(r) {
        Err(m) => Err(m),
        Ok(b) => apply(op, a, b),
      },
    },
  }

fn apply(op: Str, a: Int, b: Int) -> Result[Int, Str] =
  match op {
    "+" => Ok(a + b),
    "-" => Ok(a - b),
    "*" => Ok(a * b),
    _ => if b == 0 then Err("error: division by zero") else if op == "/" then Ok(a / b) else Ok(a % b),
  }

fn calc(line: Str) -> Str =
  match lex(chars(line), 0, []) {
    None => "error: syntax",
    Some(ts) => match expr(ts, 0) {
      Some(p) if p.pos == len(ts) => match eval(p.e) { Ok(v) => from_int(v), Err(m) => m },
      _ => "error: syntax",
    },
  }

test precedence = calc("1 + 2 * 3") == "7" && calc("(1 + 2) * 3") == "9" && calc("10 - 4 - 3") == "3" && calc("2*-3") == "-6"
test errors = calc("7 / 0") == "error: division by zero" && calc("2 +") == "error: syntax" && calc("") == "error: syntax" && calc("1/0 + (") == "error: syntax"

fn each_line() -> Int !io = match read_line() { None => 0, Some(l) => { print(calc(l)); each_line() } }

fn main(args: List[Str]) -> Int !io = each_line()

# Run-length encoding and decoding, line by line.

fn is_digit(c: Str) -> Bool = c >= "0" && c <= "9"

fn run_end(cs: List[Str], c: Str, i: Int) -> Int = match get(cs, i) { Some(d) if d == c => run_end(cs, c, i + 1), _ => i }

fn encode_from(cs: List[Str], i: Int, acc: List[Str]) -> Str =
  match get(cs, i) {
    None => join(acc, ""),
    Some(c) => let e = run_end(cs, c, i) in encode_from(cs, e, push(acc, from_int(e - i) ++ c)),
  }

fn encode(line: Str) -> Str = encode_from(chars(line), 0, [])

fn repeat(c: Str, n: Int) -> Str =
  if n <= 0 then "" else if n % 2 == 0 then let h = repeat(c, n / 2) in h ++ h else c ++ repeat(c, n - 1)

fn digits_end(cs: List[Str], i: Int) -> Int = match get(cs, i) { Some(c) if is_digit(c) => digits_end(cs, i + 1), _ => i }

fn decode_from(cs: List[Str], i: Int, acc: List[Str]) -> Str =
  if i >= len(cs) then join(acc, "")
  else
    decode_pair(cs, i, digits_end(cs, i), acc)

fn decode_pair(cs: List[Str], i: Int, e: Int, acc: List[Str]) -> Str =
  match get(cs, e) {
    Some(c) if e > i && !is_digit(c) =>
      match to_int(number(cs, i, e, "")) {
        Some(n) if n > 0 => decode_from(cs, e + 1, push(acc, repeat(c, n))),
        _ => "error",
      },
    _ => "error",
  }

fn number(cs: List[Str], i: Int, e: Int, acc: Str) -> Str =
  if i >= e then acc else number(cs, i + 1, e, acc ++ (match get(cs, i) { Some(c) => c, None => "" }))

fn decode(line: Str) -> Str = decode_from(chars(line), 0, [])

test round = encode("aaabccdddd") == "3a1b2c4d" && decode("3a1b2c") == "aaabcc" && decode("x2") == "error" && decode("0a") == "error"

fn each_line(mode: Str) -> Int !io =
  match read_line() {
    None => 0,
    Some(l) => { print(if mode == "encode" then encode(l) else decode(l)); each_line(mode) },
  }

fn main(args: List[Str]) -> Int !io =
  match get(args, 0) {
    Some(mode) if len(args) == 1 && (mode == "encode" || mode == "decode") => each_line(mode),
    _ => { print("usage: rle encode|decode"); 2 },
  }

# Statistics of a text file: lines, words, characters, longest line, most frequent word.

fn is_space(c: Str) -> Bool = c == " " || c == "\t" || c == "\r" || c == "\n"

fn space_out(c: Str) -> Str = if is_space(c) then " " else c

fn non_empty(s: Str) -> Bool = s != ""

fn words(text: Str) -> List[Str] = filter(split(join(map(chars(text), space_out), ""), " "), non_empty)

fn lines(text: Str) -> List[Str] =
  let parts = split(text, "\n") in
  match get(parts, len(parts) - 1) {
    Some("") => reverse(drop_first(reverse(parts))),
    _ => parts,
  }

fn drop_first(xs: List[Str]) -> List[Str] = filter_index(xs, 1, [])

fn filter_index(xs: List[Str], i: Int, acc: List[Str]) -> List[Str] =
  match get(xs, i) { None => acc, Some(x) => filter_index(xs, i + 1, push(acc, x)) }

fn longer(best: Int, line: Str) -> Int = if len(line) > best then len(line) else best

type Top = { word: Str, count: Int, cur: Str, run: Int }

# Over sorted words: the first word with the highest count wins ties.
fn tally(t: Top, w: Str) -> Top =
  let run = if w == t.cur then t.run + 1 else 1 in
  if run > t.count then Top { word: w, count: run, cur: w, run: run } else Top { word: t.word, count: t.count, cur: w, run: run }

test counts = lines("a\nb\n") == ["a", "b"] && lines("") == [] && lines("a\n\nb") == ["a", "", "b"] && len(words(" a\tb\n")) == 2

fn stats(text: Str) -> Int !io =
  let ws = words(text) in
  let ls = lines(text) in {
    print("lines " ++ from_int(len(ls)));
    print("words " ++ from_int(len(ws)));
    print("chars " ++ from_int(len(text)));
    print("longest " ++ from_int(fold(ls, 0, longer)));
    let t = fold(sort_str(map(ws, to_lower_word)), Top { word: "", count: 0, cur: "", run: 0 }, tally) in
    if t.count > 0 then { print("top " ++ t.word ++ " " ++ from_int(t.count)); 0 } else 0
  }

fn to_lower_word(w: Str) -> Str = to_lower(w)

fn main(args: List[Str]) -> Int !io !fs =
  match get(args, 0) {
    Some(path) if len(args) == 1 => match read_file(path) {
      Ok(text) => stats(text),
      Err(_) => { print("error: cannot read " ++ path); 1 },
    },
    _ => { print("usage: file_stats <path>"); 2 },
  }

# Prime factorization by trial division (N <= 10^12, so divisors stay below 10^6).

fn power(n: Int, d: Int, k: Int) -> Int = if n % d == 0 then power(n / d, d, k + 1) else k

fn strip(n: Int, d: Int) -> Int = if n % d == 0 then strip(n / d, d) else n

fn factor(n: Int, d: Int, acc: List[Str]) -> List[Str] =
  if d * d > n then (if n > 1 then push(acc, from_int(n)) else acc)
  else if n % d != 0 then factor(n, d + 1, acc)
  else
    let k = power(n, d, 0) in
    factor(strip(n, d), d + 1, push(acc, if k > 1 then from_int(d) ++ "^" ++ from_int(k) else from_int(d)))

fn is_digit(c: Str) -> Bool = c >= "0" && c <= "9"

fn describe(line: Str) -> Str =
  let t = trim(line) in
  let n = if t != "" && len(filter(chars(t), is_digit)) == len(t) then to_int(t) else None in
  match n {
    Some(v) if v >= 2 && v <= 1000000000000 => t ++ " = " ++ join(factor(v, 2, []), " * "),
    _ => "error",
  }

test examples = describe("360") == "360 = 2^3 * 3^2 * 5" && describe("13") == "13 = 13" && describe("1") == "error" && describe("+4") == "error"

fn each_line() -> Int !io = match read_line() { None => 0, Some(l) => { print(describe(l)); each_line() } }

fn main(args: List[Str]) -> Int !io = each_line()

# Unique lowercase words (runs of ASCII letters), sorted.

fn is_letter(c: Str) -> Bool = (c >= "a" && c <= "z") || (c >= "A" && c <= "Z")

fn letter_or_space(c: Str) -> Str = if is_letter(c) then c else " "

fn non_empty(s: Str) -> Bool = s != ""

fn words(text: Str) -> List[Str] = filter(split(to_lower(join(map(chars(text), letter_or_space), "")), " "), non_empty)

type U = { out: List[Str], last: Str }

fn unique_step(u: U, w: Str) -> U = if w == u.last then u else U { out: push(u.out, w), last: w }

fn unique(sorted: List[Str]) -> List[Str] = fold(sorted, U { out: [], last: "" }, unique_step).out

fn show(n: Int, w: Str) -> Int !io = { print(w); n + 1 }

test example = unique(sort_str(words("The quick brown fox, the lazy dog.\nA fox!"))) == ["a", "brown", "dog", "fox", "lazy", "quick", "the"]

