# The K most frequent words, by count (descending) and then alphabetically.

fn is_letter(c: Str) -> Bool = (c >= "a" && c <= "z") || (c >= "A" && c <= "Z")

fn letter_or_space(c: Str) -> Str = if is_letter(c) then c else " "

fn non_empty(s: Str) -> Bool = s != ""

fn words(text: Str) -> List[Str] = filter(split(to_lower(join(map(chars(text), letter_or_space), "")), " "), non_empty)

type Runs = { keys: List[Str], cur: Str, run: Int }

# Sort key `<10000000000 - count> <word>`: fixed width (counts < 10^9), so string order is the ranking.
fn key(word: Str, count: Int) -> Str = from_int(10000000000 - count) ++ " " ++ word

fn close(r: Runs) -> List[Str] = if r.run > 0 then push(r.keys, key(r.cur, r.run)) else r.keys

fn count_step(r: Runs, w: Str) -> Runs =
  if w == r.cur then Runs { keys: r.keys, cur: w, run: r.run + 1 } else Runs { keys: close(r), cur: w, run: 1 }

fn ranked(text: Str) -> List[Str] = sort_str(close(fold(sort_str(words(text)), Runs { keys: [], cur: "", run: 0 }, count_step)))

fn line(k: Str) -> Str =
  let parts = split(k, " ") in
  match get(parts, 0) {
    Some(c) => from_int(10000000000 - (match to_int(c) { Some(n) => n, None => 0 })) ++ " " ++ (match get(parts, 1) { Some(w) => w, None => "" }),
    None => "",
  }

test example = map(ranked("the cat and the dog and the bird"), line) == ["3 the", "2 and", "1 bird", "1 cat", "1 dog"]

fn print_top(xs: List[Str], i: Int, k: Int) -> Int !io =
  if i >= k then 0 else match get(xs, i) { None => 0, Some(x) => { print(line(x)); print_top(xs, i + 1, k) } }

fn is_digit(c: Str) -> Bool = c >= "0" && c <= "9"

fn main(args: List[Str]) -> Int !io =
  let k = match get(args, 0) {
    Some(a) if len(args) == 1 && a != "" && len(filter(chars(a), is_digit)) == len(a) => match to_int(a) { Some(n) => n, None => 0 },
    _ => 0,
  } in
  if k < 1 then { print("usage: word_freq <k>"); 2 } else print_top(ranked(read_all()), 0, k)

# Binary search tree: insert in input order, then size, height and the three traversals.

type Tree = Leaf | Node(Tree, Int, Tree)

fn insert(t: Tree, v: Int) -> Tree =
  match t {
    Leaf => Node(Leaf, v, Leaf),
    Node(l, x, r) => if v < x then Node(insert(l, v), x, r) else if v > x then Node(l, x, insert(r, v)) else t,
  }

fn height(t: Tree) -> Int = match t { Leaf => 0, Node(l, _, r) => let a = height(l) in let b = height(r) in 1 + (if a > b then a else b) }

fn inorder(t: Tree) -> List[Int] = match t { Leaf => [], Node(l, x, r) => concat(push(inorder(l), x), inorder(r)) }

fn preorder(t: Tree) -> List[Int] = match t { Leaf => [], Node(l, x, r) => concat(concat([x], preorder(l)), preorder(r)) }

fn postorder(t: Tree) -> List[Int] = match t { Leaf => [], Node(l, x, r) => push(concat(postorder(l), postorder(r)), x) }

fn is_space(c: Str) -> Bool = c == " " || c == "\t" || c == "\r" || c == "\n"

fn space_out(c: Str) -> Str = if is_space(c) then " " else c

fn non_empty(s: Str) -> Bool = s != ""

fn number(s: Str) -> Int = match to_int(s) { Some(n) => n, None => 0 }

fn numbers(text: Str) -> List[Int] = map(filter(split(join(map(chars(text), space_out), ""), " "), non_empty), number)

fn show(n: Int) -> Str = from_int(n)

fn line(name: Str, xs: List[Int]) -> Str = join(concat([name], map(xs, show)), " ")

test tree = let t = fold([5, 3, 8, 1, 4, 9, 3], Leaf, insert) in inorder(t) == [1, 3, 4, 5, 8, 9] && preorder(t) == [5, 3, 1, 4, 8, 9] && height(t) == 3

fn main(args: List[Str]) -> Int !io =
  let t = fold(numbers(read_all()), Leaf, insert) in
  let ino = inorder(t) in {
    print("size " ++ from_int(len(ino)));
    print("height " ++ from_int(height(t)));
    print(line("inorder", ino));
    print(line("preorder", preorder(t)));
    print(line("postorder", postorder(t)));
    0
  }

# Caesar cipher over ASCII letters, shift given as the argument.

fn shift_in(c: Str, base: Int, k: Int) -> Str = from_char_code((char_code(c) - base + k) % 26 + base)

fn shift(c: Str, k: Int) -> Str =
  if c >= "a" && c <= "z" then shift_in(c, 97, k) else if c >= "A" && c <= "Z" then shift_in(c, 65, k) else c

type Line = { k: Int, out: List[Str] }

fn step(l: Line, c: Str) -> Line = Line { k: l.k, out: push(l.out, shift(c, l.k)) }

fn encode(line: Str, k: Int) -> Str = join(fold(chars(line), Line { k: k, out: [] }, step).out, "")

test example = encode("Hello, World!", 3) == "Khoor, Zruog!" && encode("xyz", 3) == "abc" && encode("A", 25) == "Z"

fn each_line(k: Int) -> Int !io = match read_line() { None => 0, Some(l) => { print(encode(l, k)); each_line(k) } }

fn main(args: List[Str]) -> Int !io =
  match get(args, 0) {
    Some(a) if len(args) == 1 => match to_int(a) {
      Some(n) if n >= -1000000000 && n <= 1000000000 => each_line(((n % 26) + 26) % 26),
      _ => { print("usage: caesar <shift>"); 2 },
    },
    _ => { print("usage: caesar <shift>"); 2 },
  }

# Groups of anagrams: sort `<sorted letters> <word>` entries, then collect equal keys.

fn entry(w: Str) -> Str = join(sort_str(chars(w)), "") ++ " " ++ w

fn non_empty(s: Str) -> Bool = s != ""

type G = { lines: List[Str], key: Str, words: List[Str], last: Str }

fn close(g: G) -> List[Str] = if len(g.words) >= 2 then push(g.lines, join(g.words, " ")) else g.lines

fn part(e: Str, i: Int) -> Str = match get(split(e, " "), i) { Some(s) => s, None => "" }

fn group_step(g: G, e: Str) -> G =
  if e == g.last then g
  else if part(e, 0) == g.key then G { lines: g.lines, key: g.key, words: push(g.words, part(e, 1)), last: e }
  else G { lines: close(g), key: part(e, 0), words: [part(e, 1)], last: e }

fn groups(words: List[Str]) -> List[Str] =
  sort_str(close(fold(sort_str(map(filter(words, non_empty), entry)), G { lines: [], key: "", words: [], last: "" }, group_step)))

test example = groups(["listen", "silent", "cat", "act", "dog", "enlist", "cat"]) == ["act cat", "enlist listen silent"]

fn read_words(acc: List[Str]) -> List[Str] !io = match read_line() { None => acc, Some(l) => read_words(push(acc, trim(l))) }

fn show(n: Int, line: Str) -> Int !io = { print(line); n }

fn main(args: List[Str]) -> Int !io = fold(groups(read_words([])), 0, show)

# Greedy word wrap of paragraphs separated by blank lines.

fn is_blank(c: Str) -> Bool = c == " " || c == "\t"

fn space_out(c: Str) -> Str = if is_blank(c) then " " else c

fn non_empty(s: Str) -> Bool = s != ""

fn words_of(line: Str) -> List[Str] = filter(split(join(map(chars(line), space_out), ""), " "), non_empty)

# Paragraphs as word lists; `cur` collects the lines of the paragraph being read.
type P = { paras: List[List[Str]], cur: List[Str] }

fn close(p: P) -> List[List[Str]] = if len(p.cur) > 0 then push(p.paras, words_of(join(p.cur, " "))) else p.paras

fn para_step(p: P, line: Str) -> P =
  if len(words_of(line)) == 0 then P { paras: close(p), cur: [] } else P { paras: p.paras, cur: push(p.cur, line) }

type W = { width: Int, lines: List[Str], line: Str }

fn wrap_step(w: W, word: Str) -> W =
  if w.line == "" then W { width: w.width, lines: w.lines, line: word }
  else if len(w.line) + 1 + len(word) <= w.width then W { width: w.width, lines: w.lines, line: w.line ++ " " ++ word }
  else W { width: w.width, lines: push(w.lines, w.line), line: word }

fn wrap(words: List[Str], width: Int) -> List[Str] =
  let w = fold(words, W { width: width, lines: [], line: "" }, wrap_step) in push(w.lines, w.line)

test wrapping = wrap(["The", "quick", "brown", "fox"], 9) == ["The quick", "brown fox"] && wrap(["a", "verylong", "b"], 5) == ["a", "verylong", "b"]

fn print_lines(n: Int, l: Str) -> Int !io = { print(l); n }

fn print_paras(ps: List[List[Str]], i: Int, width: Int) -> Int !io =
  match get(ps, i) {
    None => 0,
    Some(p) => { if i > 0 then print("") else (); let n = fold(wrap(p, width), 0, print_lines) in print_paras(ps, i + 1, width) },
  }

fn read_lines(acc: List[Str]) -> List[Str] !io = match read_line() { None => acc, Some(l) => read_lines(push(acc, l)) }

fn is_digit(c: Str) -> Bool = c >= "0" && c <= "9"

fn main(args: List[Str]) -> Int !io =
  let width = match get(args, 0) {
    Some(a) if len(args) == 1 && a != "" && len(filter(chars(a), is_digit)) == len(a) => match to_int(a) { Some(n) => n, None => 0 },
    _ => 0,
  } in
  if width < 1 then { print("usage: word_wrap <width>"); 2 }
  else let p = fold(read_lines([]), P { paras: [], cur: [] }, para_step) in print_paras(close(p), 0, width)

# Days between two Gregorian dates (days-from-civil, Howard Hinnant's algorithm).

fn is_digit(c: Str) -> Bool = c >= "0" && c <= "9"

fn num(s: Str) -> Int = match to_int(s) { Some(n) => n, None => -1 }

fn leap(y: Int) -> Bool = y % 4 == 0 && (y % 100 != 0 || y % 400 == 0)

fn month_days(y: Int, m: Int) -> Int =
  match m { 2 => if leap(y) then 29 else 28, 4 => 30, 6 => 30, 9 => 30, 11 => 30, _ => 31 }

fn days_from_civil(y0: Int, m: Int, d: Int) -> Int =
  let y = if m <= 2 then y0 - 1 else y0 in
  let era = (if y >= 0 then y else y - 399) / 400 in
  let yoe = y - era * 400 in
  let doy = (153 * (if m > 2 then m - 3 else m + 9) + 2) / 5 + d - 1 in
  let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy in
  era * 146097 + doe

fn well_formed(s: Str) -> Bool =
  len(s) == 10 && slice(s, 4, 5) == "-" && slice(s, 7, 8) == "-" &&
  len(filter(chars(slice(s, 0, 4) ++ slice(s, 5, 7) ++ slice(s, 8, 10)), is_digit)) == 8

fn date(s: Str) -> Option[Int] =
  if !well_formed(s) then None
  else
    let y = num(slice(s, 0, 4)) in
    let m = num(slice(s, 5, 7)) in
    let d = num(slice(s, 8, 10)) in
    if y >= 1 && m >= 1 && m <= 12 && d >= 1 && d <= month_days(y, m) then Some(days_from_civil(y, m, d)) else None

fn diff(line: Str) -> Str =
  let ts = split(line, " ") in
  match get(ts, 0) {
    Some(a) if len(ts) == 2 => match date(a) {
      Some(x) => match get(ts, 1) { Some(b) => match date(b) { Some(y) => from_int(y - x), None => "error" }, None => "error" },
      None => "error",
    },
    _ => "error",
  }

test example = diff("2024-01-01 2024-03-01") == "60" && diff("2024-03-01 2023-03-01") == "-366" && diff("2023-02-29 2023-03-01") == "error"

fn each_line() -> Int !io = match read_line() { None => 0, Some(l) => { print(diff(l)); each_line() } }

fn main(args: List[Str]) -> Int !io = each_line()

# Conversion between bases 2..36.

fn digit_value(c: Str) -> Int =
  let k = char_code(c) in
  if k >= 48 && k <= 57 then k - 48 else if k >= 97 && k <= 122 then k - 87 else if k >= 65 && k <= 90 then k - 55 else 99

fn digit_char(v: Int) -> Str = if v < 10 then from_char_code(48 + v) else from_char_code(87 + v)

type Acc = { base: Int, value: Int, ok: Bool }

fn add_digit(a: Acc, c: Str) -> Acc =
  let v = digit_value(c) in
  if !a.ok || v >= a.base then Acc { base: a.base, value: 0, ok: false } else Acc { base: a.base, value: a.value * a.base + v, ok: true }

fn render(v: Int, base: Int, acc: Str) -> Str = if v < base then digit_char(v) ++ acc else render(v / base, base, digit_char(v % base) ++ acc)

fn is_digit(c: Str) -> Bool = c >= "0" && c <= "9"

fn base(s: Str) -> Int = if s != "" && len(filter(chars(s), is_digit)) == len(s) then (match to_int(s) { Some(n) if n >= 2 && n <= 36 => n, _ => 0 }) else 0

fn convert(line: Str) -> Str =
  let ts = split(line, " ") in
  let from = base(match get(ts, 0) { Some(t) => t, None => "" }) in
  let to = base(match get(ts, 1) { Some(t) => t, None => "" }) in
  let number = match get(ts, 2) { Some(t) => t, None => "" } in
  let neg = starts_with(number, "-") in
  let digits = if neg then slice(number, 1, len(number)) else number in
  let a = fold(chars(digits), Acc { base: from, value: 0, ok: true }, add_digit) in
  if len(ts) != 3 || from == 0 || to == 0 || digits == "" || !a.ok then "error"
  else (if neg && a.value != 0 then "-" else "") ++ render(a.value, to, "")

test example = convert("10 2 10") == "1010" && convert("16 10 ff") == "255" && convert("2 16 -1010") == "-a" && convert("10 37 5") == "error" && convert("2 36 -0") == "0"

fn each_line() -> Int !io = match read_line() { None => 0, Some(l) => { print(convert(l)); each_line() } }

fn main(args: List[Str]) -> Int !io = each_line()

# INI file queries: parse sections and keys up to `---`, then answer `section.key` queries.

type Entry = { section: Str, key: Str, value: Str }

type Ini = { entries: List[Entry], section: Str }

fn ends_with(s: Str, suffix: Str) -> Bool = len(s) >= len(suffix) && slice(s, len(s) - len(suffix), len(s)) == suffix

fn parse_line(ini: Ini, line: Str) -> Ini =
  let t = trim(line) in
  if t == "" || starts_with(t, ";") || starts_with(t, "#") then ini
  else if starts_with(t, "[") && ends_with(t, "]") then Ini { entries: ini.entries, section: trim(slice(t, 1, len(t) - 1)) }
  else match index_of(t, "=") {
    Some(i) => Ini { entries: push(ini.entries, Entry { section: ini.section, key: trim(slice(t, 0, i)), value: trim(slice(t, i + 1, len(t))) }), section: ini.section },
    None => ini,
  }

# The last assignment wins: search from the end.
fn lookup(es: List[Entry], section: Str, key: Str, i: Int) -> Str =
  match get(es, i) {
    None => "<missing>",
    Some(e) => if e.section == section && e.key == key then e.value else lookup(es, section, key, i - 1),
  }

fn query(es: List[Entry], q: Str) -> Str =
  let t = trim(q) in
  match index_of(t, ".") {
    Some(i) => lookup(es, slice(t, 0, i), slice(t, i + 1, len(t)), len(es) - 1),
    None => lookup(es, "", t, len(es) - 1),
  }

test example =
  let ini = fold(["name = demo", "[server]", "host = example.org", "port=8080", "; comment"], Ini { entries: [], section: "" }, parse_line) in
  query(ini.entries, "server.host") == "example.org" && query(ini.entries, "name") == "demo" && query(ini.entries, "server.user") == "<missing>"

fn read_ini(ini: Ini) -> Option[Ini] !io =
  match read_line() { None => None, Some("---") => Some(ini), Some(l) => read_ini(parse_line(ini, l)) }

fn answer(es: List[Entry]) -> Int !io = match read_line() { None => 0, Some(q) => { print(query(es, q)); answer(es) } }

fn main(args: List[Str]) -> Int !io =
  match read_ini(Ini { entries: [], section: "" }) { None => 0, Some(ini) => answer(ini.entries) }

# Spec §4 example: parse an age from the command line.

type Err = Empty | NotNumber(Str) | Negative(Int)

fn parse_age(s: Str) -> Result[Int, Err]
  ens match r { Ok(n) => n >= 0, _ => true }
= if len(trim(s)) == 0 then Err(Empty)
  else match to_int(trim(s)) {
    None => Err(NotNumber(s)),
    Some(n) if n < 0 => Err(Negative(n)),
    Some(n) => Ok(n),
  }

test parse_age_ok = parse_age(" 42 ") == Ok(42)
test parse_age_neg = parse_age("-1") == Err(Negative(-1))

fn main(args: List[Str]) -> Int !io
= match get(args, 0) {
    None => { print("usage: age <n>"); 2 },
    Some(a) => match parse_age(a) {
      Ok(n) => { print("ok " ++ from_int(n)); 0 },
      Err(_) => { print("invalid"); 1 },
    },
  }

# Counts lines, words and characters of a file: `qal run examples/wordcount.qal --allow io,fs:examples examples/age.qal`

type Counts = { lines: Int, words: Int, chars: Int }

fn count(text: Str) -> Counts
= Counts {
    lines: len(filter(split(text, "\n"), non_empty)) ,
    words: fold(split(text, "\n"), 0, add_words),
    chars: len(text),
  }

fn non_empty(s: Str) -> Bool = len(trim(s)) > 0

fn add_words(acc: Int, line: Str) -> Int = acc + len(filter(split(line, " "), non_empty))

test counts_words = count("a b\n\nc  d e\n") == Counts { lines: 2, words: 5, chars: 12 }

fn main(args: List[Str]) -> Int !io !fs
= match get(args, 0) {
    None => { print("usage: wordcount <file>"); 2 },
    Some(path) => match read_file(path) {
      Err(e) => { print("error: " ++ e); 1 },
      Ok(text) => {
        let c = count(text) in print(from_int(c.lines) ++ " " ++ from_int(c.words) ++ " " ++ from_int(c.chars));
        0
      },
    },
  }
